const localRender=render;let mode='b2b';const fmtDate=d=>d.split('-').reverse().join('/'),brl=c=>money(c/100);const allProducts=[...new Set(B2B_ORDERS.flatMap(o=>o.items.filter(i=>i.line!=='Acessórios').map(i=>i.item)))].sort();
const dataset=document.createElement('div');dataset.className='datasetbar';dataset.innerHTML='<div><strong>Base de gestão</strong><p id="basenote">Pedidos conferidos nos PDFs • valores de venda B2B, sem confirmação de recebimento.</p></div><select id="dataset" aria-label="Base de gestão"><option value="b2b">B2B · O Beco · 13 pedidos</option><option value="local">Vendas CSV · base deste navegador</option></select>';$('#filterbar').before(dataset);
const orderNav=document.createElement('button');orderNav.dataset.page='orders';orderNav.innerHTML='▤ <span>Pedidos e conferência</span>';document.querySelector('nav').append(orderNav);
function setMode(){mode=$('#dataset').value;page='overview';orderNav.hidden=mode!=='b2b';if(mode==='b2b'){ $('#start').value='2026-09-25';$('#end').value='2026-11-20';$('#item').innerHTML='<option value="">Todos os itens (inclui acessórios)</option>'+allProducts.map(x=>`<option>${esc(x)}</option>`).join('');$('#compare').value='none'}else{populate();$('#start').value=rows.length?rows.map(x=>x.data).sort()[0]:'2026-11-01';$('#end').value=rows.length?rows.map(x=>x.data).sort().at(-1):'2026-11-15'}$('#basenote').textContent=mode==='b2b'?'Pedidos conferidos nos PDFs • valores de venda B2B, sem confirmação de recebimento.':'CSV independente • dados salvos apenas neste navegador, sem mesclar com os pedidos B2B.';render()}
$('#dataset').onchange=setMode;
function bOrders(a,b){let item=$('#item').value;return B2B_ORDERS.filter(o=>o.date>=a&&o.date<=b).map(o=>({...o,items:o.items.filter(i=>!item||i.item===item)})).filter(o=>o.items.length)}
function summary(os){let flat=os.flatMap(o=>o.items);return {value:flat.reduce((a,i)=>a+i.value,0),qty:flat.filter(i=>i.line!=='Acessórios').reduce((a,i)=>a+i.qty,0),accessories:flat.filter(i=>i.line==='Acessórios').reduce((a,i)=>a+i.qty,0),accessoryValue:flat.filter(i=>i.line==='Acessórios').reduce((a,i)=>a+i.value,0),count:os.length,flat}}
function bProducts(os){let flat=os.flatMap(o=>o.items).filter(i=>i.line!=='Acessórios');return [...new Set(flat.map(i=>i.item))].map(item=>{let list=flat.filter(i=>i.item===item);return {item,line:list[0].line,qty:list.reduce((a,i)=>a+i.qty,0),value:list.reduce((a,i)=>a+i.value,0),prices:[...new Set(list.map(i=>i.price))]}}).sort((a,b)=>b.value-a.value)}
function table(headers,body){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="emptycell">Nenhum pedido neste recorte. Ajuste os filtros.</td></tr>`}</tbody></table></div>`}
function alerts(){return `<div class="insightgrid"><div class="insight"><span class="tag fact">Conferido</span><h3>13 pedidos, sem duplicidades</h3><p>Sequência 000001–000013. Quantidades × preços e totais dos documentos conferem.</p></div><div class="insight"><span class="tag hyp">Conferir condição comercial</span><h3>Preços menores desde 26/10</h3><p>Fresh: R$ 18,70 → R$ 17,50 (−6,4%). Demais: R$ 20,50 → R$ 18,50 (−9,8%).</p></div><div class="insight"><span class="tag hyp">Qualidade dos dados</span><h3>Duas observações de entrega</h3><p>000001 reúne entregas de 23 a 25/09. 000010 não informa entrega. Os filtros usam emissão.</p></div></div>`}
render=function(){if(mode!=='b2b'||page==='research'||page==='data'){if(page==='orders')page='overview';localRender();if(page==='data'&&mode==='b2b')$('#content').insertAdjacentHTML('afterbegin','<div class="banner"><div><strong>Os 13 pedidos B2B já estão integrados e disponíveis em qualquer dispositivo.</strong><p>A importação abaixo pertence à base CSV independente. Ela não substitui os pedidos conferidos. Para visualizar o CSV, selecione essa base no topo.</p></div></div>');return}let r;try{r=range()}catch(e){$('#filtermsg').textContent=e.message;return}let os=bOrders(r.a,r.b),s=summary(os),ps=summary(bOrders(r.pa,r.pb)),products=bProducts(os),scope=$('#item').value;let config={overview:['Do pedido à próxima decisão.','Vendas B2B do Gelato para O Beco • base documental conferida.'],menu:['Sabores que movimentam o Beco.','Giro em unidades fornecidas ao cliente B2B. Não equivale à venda ao consumidor.'],retention:['A frequência do parceiro.','Histórico de reposição de um cliente comercial. Recorrência B2C ainda sem dados.'],insights:['O que os pedidos estão dizendo.','Evidências, limites da base e próximos passos de gestão.'],orders:['Cada pedido, conferido.','Rastreabilidade por documento, com datas, itens e valores originais.']}[page];$('#title').textContent=config[0];$('#subtitle').textContent=config[1];$('#crumb').textContent='B2B · '+({overview:'Visão geral',menu:'Sabores',retention:'Reposição',insights:'Insights',orders:'Pedidos'})[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#filterbar').style.display='flex';$('#filtermsg').textContent=`${os.length} pedidos no recorte • emissão: ${fmtDate(r.a)} a ${fmtDate(r.b)}${scope?' • valores referentes apenas a '+scope:''} • base cobre 25/09 a 20/11/2026`;
let html='';const kpis=`<div class="cards">${kpi('Faturamento em pedidos',brl(s.value),($('#compare').value==='none'?'Comparação desativada':r.pa<'2026-09-25'||r.b>'2026-11-20'?'Cobertura insuficiente para comparar':delta(s.value,ps.value)))}${kpi('Gelatos fornecidos',num(s.qty),'Acessórios excluídos do volume')}${kpi('Pedidos B2B',s.count,'Cliente: O Beco')}${kpi(scope?'Valor médio do sabor por pedido':'Ticket médio B2B',s.count?brl(s.value/s.count):'—','Valor do recorte ÷ pedidos')}</div><p class="tiny">No recorte: gelatos ${brl(s.value-s.accessoryValue)} + acessórios ${brl(s.accessoryValue)} (${s.accessories} unidades). O faturamento total inclui ambos; o ranking e o volume de gelatos excluem acessórios.</p>`;
if(page==='overview'){let monthKeys=[...new Set(os.map(o=>o.date.slice(0,7)))],months=monthKeys.map(m=>({m,...summary(os.filter(o=>o.date.startsWith(m)))})),max=Math.max(...months.map(m=>m.value),1);html=`<div class="banner"><span class="icon">✓</span><div><strong>Base real integrada · 13 PDFs · 1 cliente comercial</strong><p>R$ 24.859,60 em pedidos e 1.284 gelatos e 10 sacolas térmicas na base completa. Custos, pagamentos e venda ao consumidor não informados.</p></div><button data-page="orders">Conferir pedidos →</button></div>${kpis}<div class="grid"><div class="panel"><h2>Faturamento por mês</h2><p>Meses parciais: setembro desde 25/09; novembro até 20/11. Não comparar como meses completos.</p>${months.map(m=>`<div class="monthrow"><div><strong>${m.m.split('-').reverse().join('/')}</strong><span>${brl(m.value)}</span></div><div class="bar"><i style="width:${m.value/max*100}%"></i></div><small>${m.count} pedidos · ${m.qty} gelatos · ${m.accessories} acessórios</small></div>`).join('')||'<p>Nenhum pedido no período.</p>'}</div><div class="panel"><h2>Sabores em destaque</h2><p>Receita B2B no recorte</p>${products.slice(0,5).map((p,i)=>`<div class="listrow"><span class="number">${i+1}</span><div><strong>${p.item}</strong><p>${p.line} · ${p.qty} unidades</p></div><span>${brl(p.value)}</span></div>`).join('')}</div></div><div class="sectionhead"><h2>Atenção à gestão</h2><span>Sem confundir pedido com caixa</span></div>${alerts()}`}
if(page==='menu'){html=`${kpis}<div class="panel" style="margin-top:22px"><h2>Giro e participação por sabor</h2><p>Custo e margem permanecem em aberto: os PDFs trazem preços de venda, não fichas de custo.</p>${table(['SABOR / LINHA','UNIDADES','VALOR B2B','% UNIDADES','PREÇOS UNITÁRIOS','MARGEM'],products.map(p=>`<tr><td>${p.item}<p>${p.line}</p></td><td>${p.qty}</td><td>${brl(p.value)}</td><td>${(p.qty/s.qty*100).toFixed(1)}%</td><td>${p.prices.map(brl).join(' / ')}</td><td>Sem custo</td></tr>`).join(''))}</div><div class="panel" style="margin-top:22px"><h2>Comparação direta de sabores</h2><p>No mesmo período, independente do filtro de sabor acima.</p><div class="compareitems"><select id="bA" aria-label="Primeiro sabor">${allProducts.map(p=>`<option>${p}</option>`).join('')}</select><select id="bB" aria-label="Segundo sabor">${allProducts.map(p=>`<option>${p}</option>`).join('')}</select></div><div id="bResult"></div></div>`}
if(page==='retention'){let dates=os.map(o=>Date.parse(o.date)),gaps=dates.slice(1).map((d,i)=>(d-dates[i])/864e5),avg=gaps.length?gaps.reduce((a,b)=>a+b,0)/gaps.length:null;html=`<div class="cards">${kpi('Cliente comercial',os.length?'1':'0','O Beco')}${kpi('Pedidos no período',s.count,'Histórico de fornecimento')}${kpi('Intervalo médio',avg===null?'—':avg.toFixed(1)+' dias','Entre emissões consecutivas no recorte')}${kpi('Último pedido na base','20/11/2026','Não indica ausência de compras posteriores')}</div><div class="panel" style="margin-top:22px"><h2>Cadência de reposição</h2><p>Use a frequência como referência para conversar sobre estoque. Sem saldo atual, não é possível recomendar quantidade de reposição.</p>${table(['EMISSÃO','PEDIDO','INTERVALO ANTERIOR','UNIDADES','VALOR'],os.map((o,i)=>`<tr><td>${fmtDate(o.date)}</td><td>${o.id}</td><td>${i?gaps[i-1]+' dias':'—'}</td><td>${summary([o]).qty} gelatos${summary([o]).accessories?' + '+summary([o]).accessories+' acessórios':''}</td><td>${brl(summary([o]).value)}</td></tr>`).join(''))}<div class="note"><p>Todos os pedidos pertencem ao mesmo cliente B2B. Não exibimos uma taxa de recorrência de consumidores com esses documentos. Para isso, use a base CSV com IDs anônimos dos compradores finais.</p></div></div>`}
if(page==='orders'){html=`<div class="panel"><div class="panelhead"><div><h2>Conferência dos pedidos</h2><p>Valores por emissão. Com filtro de sabor, unidades e valores mostram apenas o sabor escolhido.</p></div><button class="action" id="bexport">↓ Exportar recorte CSV</button></div>${table(['PEDIDO','EMISSÃO','ENTREGA','UNIDADES','VALOR','PAGAMENTO','CONFERÊNCIA'],os.map(o=>`<tr><td><button class="orderdetail" data-order="${o.id}">${o.id} ↗</button></td><td>${fmtDate(o.date)}</td><td>${o.delivery||'Não informada'}${o.id==='000001'?'<p>Obs.: 23, 24 e 25/09</p>':''}</td><td>${summary([o]).qty} gelatos${summary([o]).accessories?' + '+summary([o]).accessories+' acessórios':''}</td><td>${brl(summary([o]).value)}</td><td><span class="tag">Não confirmado</span></td><td><a href="${o.source}" target="_blank" rel="noopener">PDF original ↗</a></td></tr>`).join(''))}<p>Total do recorte: <strong>${brl(s.value)}</strong> · ${s.qty} gelatos + ${s.accessories} acessórios.</p></div><div id="orderDetails"></div><div class="note"><p>Forma declarada: PIX à vista. Sem comprovantes, nenhum pedido foi marcado como pago ou em atraso. Nenhum arquivo original foi alterado.</p></div>`}
if(page==='insights'){let raw=B2B_ORDERS.filter(o=>o.date>='2026-10-26'),impact=raw.flatMap(o=>o.items).filter(i=>i.line!=='Acessórios').reduce((a,i)=>a+((i.line==='Fresh'?1870:2050)-i.price)*i.qty,0);html=`${alerts()}<div class="panel" style="margin-top:22px"><h2>Impacto da nova tabela de preços</h2><div class="value" style="font-size:32px;margin:20px 0">${brl(impact)}</div><p>Diferença aritmética nos pedidos 000009–000013 entre os preços efetivamente usados e a tabela anterior, mantendo as mesmas quantidades. Base fixa: 26/10 a 20/11/2026; este cálculo não usa os filtros acima.</p><p><strong>Não é perda comprovada nem margem:</strong> o desconto pode ter alterado a demanda e não há custos informados.</p></div><div class="sectionhead"><h2>Prioridades para a próxima decisão</h2></div><div class="insightgrid"><div class="insight"><span class="tag hyp">Ação sugerida</span><h3>Confirmar a nova tabela</h3><p>Validar se a redução desde o pedido 000009 é permanente ou promocional antes da próxima cobrança.</p></div><div class="insight"><span class="tag hyp">Dados necessários</span><h3>Medir venda e estoque da loja</h3><p>Reposição não é consumo final. Obter estoque, perdas e vendas por sabor para detectar baixo giro de verdade.</p></div><div class="insight"><span class="tag hyp">Dados necessários</span><h3>Completar custos e recebimentos</h3><p>Relacionar fichas de custo e comprovantes aos pedidos. Só então calcular contribuição e contas a receber.</p></div></div><div class="note"><p>Novembro é parcial e a base termina em 20/11. Não há evidência suficiente para afirmar queda de demanda, inadimplência ou desperdício. Compare períodos equivalentes após completar a cobertura dos dados.</p></div>`}
$('#content').innerHTML=html;
if(page==='menu'){ $('#bB').selectedIndex=1;let comp=()=>{let all=B2B_ORDERS.filter(o=>o.date>=r.a&&o.date<=r.b);$('#bResult').innerHTML='<div class="cards">'+[$('#bA').value,$('#bB').value].map(n=>{let q=summary(all.map(o=>({...o,items:o.items.filter(i=>i.item===n)})).filter(o=>o.items.length));return kpi(n,brl(q.value),q.qty+' unidades · '+q.count+' pedidos')}).join('')+'</div>'};$('#bA').onchange=comp;$('#bB').onchange=comp;comp()}
if(page==='orders'){$('#bexport').onclick=()=>download('pedidos-b2b-beco.csv',['pedido;emissao;entrega;item;quantidade;preco_unitario;valor_linha;pagamento',...os.flatMap(o=>o.items.map(i=>[o.id,o.date,o.delivery||'',i.item,i.qty,(i.price/100).toFixed(2),(i.value/100).toFixed(2),'nao_confirmado'].join(';')))].join('\n'));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{let o=B2B_ORDERS.find(o=>o.id===b.dataset.order);$('#orderDetails').innerHTML=`<div class="panel" style="margin-top:22px"><h2>Pedido ${o.id} · documento completo</h2>${table(['ITEM','LINHA / CATEGORIA','UNIDADES','PREÇO','TOTAL'],o.items.map(i=>`<tr><td>${i.item}</td><td>${i.line}</td><td>${i.qty}</td><td>${brl(i.price)}</td><td>${brl(i.value)}</td></tr>`).join(''))}<p>Total original: <strong>${brl(o.total)}</strong> · <a href="${o.source}" target="_blank" rel="noopener">Abrir PDF original ↗</a></p></div>`;$('#orderDetails').scrollIntoView({behavior:'smooth',block:'start'})})}
};
$('#apply').onclick=()=>render();setMode();
